column4:
SELECT customer_id, customer_status
FROM customers
WHERE customer_status NOT IN ('ACTIVE','INACTIVE');

SELECT customer_id, date_of_birth
FROM customers
WHERE date_of_birth > '2026-10-02';

SELECT account_id, account_status
FROM accounts
WHERE account_status NOT IN ('ACTIVE','CLOSED','SUSPENDED');

SELECT transaction_id, transaction_type
FROM transactions
WHERE transaction_type NOT IN ('PURCHASE','PAYMENT','WITHDRAWAL','DEPOSIT','FEE','TRANSFER');

SELECT transaction_id, amount
FROM transactions
WHERE CAST(amount AS REAL) <= 0;

SELECT COUNT(*)
FROM customers
WHERE last_updated < datetime('2026-10-02 12:00:00','-24 hours');

SELECT COUNT(*)
FROM accounts
WHERE last_updated < datetime('2026-10-02 12:00:00','-24 hours');
